import unittest

from dag import dependency_batches


class DependencyBatchesTests(unittest.TestCase):
    def test_empty_and_stably_sorted_waves(self) -> None:
        self.assertEqual(dependency_batches({}), [])
        tasks = {"d": ["z", "c"], "c": ["b", "a"], "b": [], "z": ["a"], "a": []}
        self.assertEqual(dependency_batches(tasks), [["a", "b"], ["c", "z"], ["d"]])

    def test_repeated_dependencies_are_ignored(self) -> None:
        self.assertEqual(
            dependency_batches({"b": ["a", "a"], "a": []}),
            [["a"], ["b"]],
        )

    def test_missing_dependency_error_is_stable(self) -> None:
        with self.assertRaisesRegex(ValueError, "^missing dependency: a -> x$"):
            dependency_batches({"z": ["missing"], "a": ["x"]})

    def test_cycle_error(self) -> None:
        with self.assertRaisesRegex(ValueError, "^dependency cycle$"):
            dependency_batches({"a": ["b"], "b": ["a"]})

    def test_invalid_identifier_error(self) -> None:
        with self.assertRaisesRegex(
            ValueError, "^task identifiers must be non-empty strings$"
        ):
            dependency_batches({"": []})

