import unittest

from merge_patch import merge_patch


class MergePatchTests(unittest.TestCase):
    def test_nested_merge_delete_and_array_replace(self) -> None:
        target = {"keep": 1, "nested": {"drop": 2, "stay": 3}, "items": [1, 2]}
        patch = {"nested": {"drop": None, "add": 4}, "items": [9]}
        self.assertEqual(
            merge_patch(target, patch),
            {"keep": 1, "nested": {"stay": 3, "add": 4}, "items": [9]},
        )
        self.assertEqual(target, {"keep": 1, "nested": {"drop": 2, "stay": 3},
                                  "items": [1, 2]})
        self.assertEqual(patch, {"nested": {"drop": None, "add": 4}, "items": [9]})

    def test_object_patch_replaces_non_object_target(self) -> None:
        self.assertEqual(merge_patch([1, 2], {"added": True}), {"added": True})

    def test_non_object_patch_replaces_target(self) -> None:
        self.assertEqual(merge_patch({"old": 1}, [2, 3]), [2, 3])
        self.assertIsNone(merge_patch({"old": 1}, None))

