import unittest

from usage_totals import aggregate_usage


class AggregateUsageTests(unittest.TestCase):
    def test_duplicate_identical_receipts_are_idempotent(self) -> None:
        first = {"id": " call-1 ", "input_tokens": 5, "output_tokens": 2,
                 "settled_cents": 1}
        second = {"id": "call-2", "input_tokens": 3, "output_tokens": 4,
                  "settled_cents": 2}
        expected = {"calls": 2, "input_tokens": 8, "output_tokens": 6,
                    "settled_cents": 3}
        self.assertEqual(aggregate_usage([first, second, first]), expected)
        self.assertEqual(aggregate_usage([first, first, second, second]), expected)

    def test_unknown_counters_stay_unknown_independently(self) -> None:
        records = [
            {"id": "a", "input_tokens": 2, "output_tokens": 3, "settled_cents": None},
            {"id": "b", "input_tokens": None, "output_tokens": 4, "settled_cents": 1},
        ]
        self.assertEqual(
            aggregate_usage(records),
            {"calls": 2, "input_tokens": None, "output_tokens": 7, "settled_cents": None},
        )

    def test_conflicting_and_malformed_receipts_are_rejected(self) -> None:
        base = {"id": "same", "input_tokens": 1, "output_tokens": 2, "settled_cents": 3}
        changed = {**base, "output_tokens": 9}
        with self.assertRaisesRegex(
            ValueError, "^conflicting usage record: same$"
        ):
            aggregate_usage([base, changed])
        with self.assertRaisesRegex(ValueError, "^invalid usage record$"):
            aggregate_usage([{**base, "input_tokens": True}])

    def test_empty_input_has_zero_totals(self) -> None:
        self.assertEqual(
            aggregate_usage([]),
            {"calls": 0, "input_tokens": 0, "output_tokens": 0, "settled_cents": 0},
        )
